CREATE FUNCTION public.reserve_photo(_path text,_style text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor uuid:=auth.uid(); job uuid; quota integer; BEGIN IF actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=actor) OR _path NOT LIKE actor::text||'/%' OR _style NOT IN('sakura','cinematic','manga') OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='profile-originals' AND name=_path AND owner_id=actor::text) THEN RAISE EXCEPTION 'Save your profile and upload your own photo first'; END IF; IF _style<>'sakura' AND NOT public.is_premium(actor) THEN RAISE EXCEPTION 'Additional styles require premium'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(actor::text,1)); quota:=CASE WHEN public.is_premium(actor) THEN 10 ELSE 2 END; IF (SELECT count(*) FROM public.photo_jobs WHERE user_id=actor AND created_at>=date_trunc('month',now()))>=quota THEN RAISE EXCEPTION 'Monthly anime photo conversion allowance reached'; END IF; IF EXISTS(SELECT 1 FROM public.photo_jobs WHERE user_id=actor AND original_path=_path) THEN RAISE EXCEPTION 'This photo was already submitted; upload a new photo for a fresh attempt'; END IF; INSERT INTO public.photo_jobs(user_id,original_path,style) VALUES(actor,_path,_style) RETURNING id INTO job; RETURN job; END $$; REVOKE ALL ON FUNCTION public.reserve_photo(text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_photo(text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.is_verified(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.account_details d WHERE d.user_id=_user_id AND d.birth_date <= (CURRENT_DATE-INTERVAL '18 years')::date) AND COALESCE((SELECT status='approved' FROM public.identity_submissions WHERE user_id=_user_id ORDER BY submitted_at DESC LIMIT 1),false) $$;
ALTER POLICY profile_read ON public.profiles USING(id=auth.uid() OR (public.is_verified(auth.uid()) AND public.is_verified(id) AND NOT public.pair_blocked(id,auth.uid())) OR public.has_role(auth.uid(),'admin'));
CREATE INDEX community_chat_order ON public.room_messages(room_id,created_at);
CREATE INDEX photo_job_owner_date ON public.photo_jobs(user_id,created_at);